"""Small OpenAI Responses client; credentials stay outside the deliverable.

Only the Python standard library is required.  There are no automatic retries,
model substitutions, or global configuration changes.  Public exceptions contain
sanitized diagnostics, never request headers, attachment data, or source text.
"""

from __future__ import annotations

import base64
import json
import mimetypes
import os
from pathlib import Path
import re
import urllib.error
import urllib.parse
import urllib.request


class GatewayError(RuntimeError):
    """Failure whose message and metadata are safe to write to a run journal."""

    def __init__(self, message: str, metadata: dict | None = None):
        super().__init__(message)
        self.metadata = metadata or {}


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # Never forward Authorization to a redirect target.
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def _safe_text(value, secret: str = "", limit: int = 500) -> str:
    text = str(value)
    if secret:
        text = text.replace(secret, "[REDACTED]")
    text = re.sub(r"data:[^\s\"']{0,100};base64,[A-Za-z0-9+/=]+", "[REDACTED_IMAGE]", text)
    text = re.sub(r"(?i)Bearer\s+[^\s\"']+", "Bearer [REDACTED]", text)
    text = re.sub(r"sk[-_][A-Za-z0-9_.-]{8,}", "[REDACTED_KEY]", text)
    text = re.sub(r'(?i)([\"\']?(?:api[_-]?key|access[_-]?token|authorization|password)[\"\']?\s*[:=]\s*)[\"\']?[^\s,}\"\']+', r"\1[REDACTED]", text)
    return text[:limit]


def load_binding(path: str | Path) -> dict:
    """Read non-secret configuration; defer credential reads until a call.

    Relative credential source paths are resolved against the binding file.
    The returned dictionary never contains the loaded API key.
    """
    binding_path = Path(path).expanduser().resolve()
    try:
        binding = json.loads(binding_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        raise GatewayError("Cannot read the gateway binding JSON.") from None
    if not isinstance(binding, dict):
        raise GatewayError("Gateway binding must be a JSON object.")
    if binding.get("protocol") != "openai_responses":
        raise GatewayError("Only protocol=openai_responses is supported.")
    if not isinstance(binding.get("model"), str) or not binding["model"].strip():
        raise GatewayError("Gateway binding requires a model.")
    parsed = urllib.parse.urlsplit(str(binding.get("base_url", "")))
    if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise GatewayError("Gateway base_url must be an HTTPS URL without credentials or query parameters.")
    credential = binding.get("credential")
    if not isinstance(credential, dict):
        raise GatewayError("Gateway binding requires a credential reference.")
    if any(key in binding for key in ("api_key", "key", "token")):
        raise GatewayError("Keep credentials outside the binding; use a credential reference.")
    credential = dict(credential)
    if credential.get("source_path"):
        source = Path(credential["source_path"]).expanduser()
        if not source.is_absolute():
            source = binding_path.parent / source
        credential["source_path"] = str(source.resolve())
    return {**binding, "credential": credential, "base_url": binding["base_url"].rstrip("/")}


def _json_pointer(document, pointer: str):
    if pointer == "":
        return document
    if not pointer.startswith("/"):
        raise ValueError("Invalid JSON pointer")
    current = document
    for segment in pointer[1:].split("/"):
        segment = segment.replace("~1", "/").replace("~0", "~")
        current = current[int(segment)] if isinstance(current, list) else current[segment]
    return current


def _load_credential(binding: dict) -> str:
    config = binding.get("credential", {})
    override_name = config.get("env_override")
    override = os.environ.get(override_name, "") if override_name else ""
    if override:
        return override.strip()
    if config.get("kind") == "env":
        value = os.environ.get(config.get("env_name") or config.get("name", ""), "")
    elif config.get("kind") == "json_field":
        try:
            document = json.loads(Path(config["source_path"]).read_text(encoding="utf-8"))
            # When the reference is a Feishu message, verify its provenance too.
            pointer = config.get("json_pointer", "")
            source_message_id = config.get("source_message_id")
            if source_message_id and pointer.endswith("/content"):
                message = _json_pointer(document, pointer.rsplit("/", 1)[0])
                if message.get("message_id") != source_message_id:
                    raise ValueError("Credential source message mismatch")
                sender_app_id = config.get("sender_app_id")
                if sender_app_id and message.get("sender", {}).get("id") != sender_app_id:
                    raise ValueError("Credential source sender mismatch")
            value = _json_pointer(document, pointer)
            if config.get("extract_regex"):
                match = re.search(config["extract_regex"], str(value))
                if not match:
                    raise ValueError("Credential pattern did not match")
                value = match.group(1)
        except (OSError, KeyError, IndexError, TypeError, ValueError, re.error):
            raise GatewayError("Cannot load the credential from the configured private source.") from None
    else:
        raise GatewayError("Supported credential kinds are env and json_field.")
    if not isinstance(value, str) or not value.strip():
        raise GatewayError("Gateway credential is empty or unavailable.")
    return value.strip()


def _error_body(body: bytes, secret: str) -> str:
    """Only expose error fields; arbitrary upstream response bodies stay private."""
    try:
        data = json.loads(body.decode("utf-8", errors="replace"))
    except (ValueError, TypeError):
        return "upstream returned a non-JSON error"
    error = data.get("error", {}) if isinstance(data, dict) else {}
    if isinstance(error, dict):
        fields = {key: error[key] for key in ("type", "code", "message") if key in error}
        return _safe_text(json.dumps(fields, ensure_ascii=False), secret)
    return _safe_text(error, secret) if error else "upstream rejected the request"


def call_json(
    binding: dict,
    system_prompt: str,
    user_text: str,
    images: list[dict],
    max_output_tokens: int = 12000,
    reasoning_effort: str = "high",
